import { DashboardWidget, type DashboardWidgetToggleDetail } from '@absoluteui/components/dashboard-widget';

const host = document.createElement('section');
const body = document.createElement('p');
body.textContent = '1,204 open tickets';
host.append(body);
document.body.append(host);

const widget = DashboardWidget.create(host, { title: 'Support queue', subtitle: 'Updated hourly', headingLevel: 2 });
host.addEventListener('aui-toggle', (event) => {
  const { collapsed } = (event as CustomEvent<DashboardWidgetToggleDetail>).detail;
  host.dataset.collapsed = String(collapsed && widget.collapsed);
});

import { DashboardGrid } from '@absoluteui/components/dashboard-grid';
import { DashboardWidget, type DashboardWidgetActionDetail, type DashboardWidgetRemoveDetail } from '@absoluteui/components/dashboard-widget';

const gridHost = document.createElement('div');
const widgetHost = document.createElement('section');
widgetHost.dataset.auiItem = 'sales';
gridHost.append(widgetHost);
document.body.append(gridHost);

const grid = DashboardGrid.create(gridHost, { label: 'Overview', items: [{ id: 'sales', x: 0, y: 0, w: 6, h: 3 }], editable: true });
const widget = DashboardWidget.create(widgetHost, {
  title: 'Sales',
  removable: true,
  busy: true,
  actions: [{ id: 'refresh', label: 'Refresh sales', icon: 'refresh' }],
});
widgetHost.addEventListener('aui-action', (event) => {
  const { id } = (event as CustomEvent<DashboardWidgetActionDetail>).detail;
  if (id === 'refresh') widget.update({ busy: true });
});
widgetHost.addEventListener('aui-remove', (event) => {
  const { id } = (event as CustomEvent<DashboardWidgetRemoveDetail>).detail;
  if (id !== null) grid.removeItem(id);
});
